/** Return every section on this source page, in the book's section order. */
export function transcriptionLinksForSourcePage(
  printedPage: string | number | null,
  pdfPage: number,
  relativePath: string,
): readonly TranscriptionLink[] {
  const links =
    printedPage === null
      ? transcriptionLinksByPdfPage[String(pdfPage)]
      : transcriptionLinksByPrintedPage[String(printedPage)];
  const prefix = relativePath
    .replace(/^\/+/, "")
    .startsWith("docs/elementary-topology/")
    ? "/docs/elementary-topology"
    : "";
  return (links ?? []).map((link) => ({ ...link, href: prefix + link.href }));
}
